import {number,finalNeeded,minimumDisplayed} from './math.js';
const EPS=1e-8;
export function parseGrades(text){
 const parts=String(text??'').trim().split(/[,\s]+/).filter(Boolean);
 if(!parts.length||parts.length>1000)throw new Error('Enter between 1 and 1,000 percentage grades.');
 return parts.map((x,i)=>number(x,`Grade ${i+1}`));
}
export function parseTriples(text){
 const lines=String(text??'').trim().split(/\n+/).filter(x=>x.trim());
 if(!lines.length||lines.length>1000)throw new Error('Enter between 1 and 1,000 rows.');
 return lines.map((line,i)=>{const p=line.split(',').map(x=>x.trim());if(p.length!==3)throw new Error(`Row ${i+1} needs exactly three comma-separated numbers.`);return p.map((x,j)=>number(x,`Value ${j+1} in row ${i+1}`,0,1e7));});
}
export function calculateExtra(kind,v){
 const n=(key,min=0,max=100)=>number(v[key],key.replaceAll('_',' '),min,max);
 const count=(key,min=0)=>{const x=n(key,min,1e6);if(!Number.isInteger(x))throw new Error(`${key.replaceAll('_',' ')} must be a whole number.`);return x;};
 const result=(label,raw,unit,description)=>({label,raw,value:Number.isFinite(raw)?raw.toFixed(2)+unit:String(raw),description});
 const target=(raw,limit=100,unit='%')=>({label:'MINIMUM REQUIRED',raw,value:raw>limit+EPS?'Not reachable':minimumDisplayed(Math.max(0,raw)).toFixed(2)+unit,description:raw>limit+EPS?`This exceeds the allowed maximum of ${limit}${unit}. Check inputs or choose a lower target.`:raw<=0?'The target is already secured under this mathematical model. Separate course requirements still apply.':'Minimum rounded upward to two decimal places. Follow the rounding and pass rules in your syllabus.'});
 switch(kind){
 case 'remaining':{const w=n('completed_weight',0.000001,99.999999),p=n('earned_contribution',0,w),t=n('target');return target((t-p)/(1-w/100));}
 case 'points-target':{const possible=n('completed_possible',0,1e7),earned=n('earned',0,possible),left=n('remaining_points',0.000001,1e7),t=n('target');const required=t/100*(possible+left)-earned;const r=target(required,left,' points');r.description+=` Required share of remaining marks: ${Math.max(0,required/left*100).toFixed(2)}%.`;return r;}
 case 'assignment-target':{const c=n('current_average'),done=count('completed_count',1),left=count('remaining_count',1),t=n('target');return target((t*(done+left)-c*done)/left);}
 case 'improvement':{const c=n('current_grade'),old=n('old_score'),next=n('new_score'),w=n('weight',0.000001)/100;const rest=c-old*w;if(rest<-EPS||rest>100*(1-w)+EPS)throw new Error('The current grade and old score are inconsistent with this assessment weight.');return result('REVISED COURSE GRADE',c+(next-old)*w,'%',`Change: ${((next-old)*w).toFixed(2)} percentage points. Assumes the old mark is replaced, with all weights unchanged.`);}
 case 'drop-lowest':{const values=parseGrades(v.grades).sort((a,b)=>a-b),drop=count('drop_count');if(drop>=values.length)throw new Error('Keep at least one grade after dropping scores.');const kept=values.slice(drop);return result('AVERAGE AFTER DROPPING',kept.reduce((a,b)=>a+b,0)/kept.length,'%',`${drop} lowest scores removed; ${kept.length} equally weighted scores remain. Original average: ${(values.reduce((a,b)=>a+b,0)/values.length).toFixed(2)}%.`);}
 case 'must-pass':{const needed=finalNeeded(v.current_grade,v.course_pass,v.final_weight),minimum=n('exam_pass');return target(Math.max(needed,minimum));}
 case 'two-part':{const needed=finalNeeded(v.current_grade,v.target,v.final_weight),p=n('part_one_weight',0,99.999999)/100,s=n('part_one_score');return target((needed-p*s)/(1-p));}
 case 'test-category':{const c=n('current_grade'),t=n('target'),w=n('test_weight',0.000001)/100,a=n('test_average'),done=count('test_count',1),k=n('final_equivalent',0.000001,100);const rest=c-w*a;if(rest<-EPS||rest>100*(1-w)+EPS)throw new Error('The test average, current grade and category weight are inconsistent.');return target((((t-c+w*a)/w)*(done+k)-a*done)/k);}
 case 'negative-marking':{const total=count('total_questions',1),correct=count('correct'),wrong=count('incorrect'),per=n('marks_per_correct',0.000001,1000),penalty=n('penalty',0,1000);if(correct+wrong>total)throw new Error('Correct plus incorrect answers cannot exceed the total.');const score=correct*per-wrong*penalty;return result('RAW EXAM SCORE',score,' marks',`${(score/(total*per)*100).toFixed(2)}% of maximum marks. ${total-correct-wrong} unanswered. No zero floor, curve or scaling applied.`);}
 case 'minimum-correct':{const total=count('total_questions',1),t=n('target'),required=Math.ceil(total*t/100-1e-10);return {label:'MINIMUM CORRECT ANSWERS',raw:required,value:String(required),description:`At most ${total-required} incorrect or unanswered. ${required}/${total} gives ${(required/total*100).toFixed(2)}%; equal-value questions only.`};}
 case 'rubric':{let points=0,weight=0;for(const [i,[earned,possible,w]] of parseTriples(v.rows).entries()){if(possible<=0||w<=0||earned>possible)throw new Error(`Row ${i+1}: use positive possible marks and weight, with earned marks no greater than possible.`);points+=earned/possible*100*w;weight+=w;}if(Math.abs(weight-100)>EPS)throw new Error('Rubric weights must total 100%.');return result('RUBRIC GRADE',points/100,'%','Each criterion is converted to a percentage before its weight is applied. All rubric criteria must be included.');}
 case 'statistics':{const a=parseGrades(v.grades).sort((a,b)=>a-b),mean=a.reduce((s,x)=>s+x,0)/a.length,mid=Math.floor(a.length/2),median=a.length%2?a[mid]:(a[mid-1]+a[mid])/2,sd=Math.sqrt(a.reduce((s,x)=>s+(x-mean)**2,0)/a.length);return result('MEDIAN GRADE',median,'%',`Mean: ${mean.toFixed(2)}%. Population standard deviation: ${sd.toFixed(2)} percentage points. Range: ${(a.at(-1)-a[0]).toFixed(2)} points across ${a.length} grades.`);}
 case 'percentile':{const below=count('below'),equal=count('equal',1),above=count('above'),total=below+equal+above;return result('MIDRANK PERCENTILE',(below+0.5*equal)/total*100,'',`${total} students in the group. This uses half of tied scores; it is a relative standing, not a percentage exam mark.`);}
 case 'attendance':{const held=count('classes_held',1),attended=count('attended');if(attended>held)throw new Error('Attended classes cannot exceed classes held.');return result('ATTENDANCE',attended/held*100,'%',`${held-attended} classes missed out of ${held}. All classes count equally; excused-absence policies are not applied.`);}
 case 'attendance-target':{const held=count('classes_held',1),attended=count('attended'),t=n('target',0.000001)/100;if(attended>held)throw new Error('Attended classes cannot exceed classes held.');if(t===1&&attended<held)return {label:'CONSECUTIVE CLASSES NEEDED',raw:null,value:'Not reachable',description:'After missing a class, perfect lifetime attendance cannot be restored by attending more classes.'};const required=attended/held>=t-EPS?0:Math.ceil((t*held-attended)/(1-t)-1e-10);return {label:'CONSECUTIVE CLASSES NEEDED',raw:required,value:String(required),description:`Attend the next ${required} classes without another absence. Resulting attendance: ${((attended+required)/(held+required)*100).toFixed(2)}%.`};}
 case 'target-gpa':{const max=n('scale',1,10),old=n('current_gpa',0,max),credits=n('current_credits',0,1e5),goal=n('target_gpa',0,max),next=n('next_credits',0.000001,1e5);return target((goal*(credits+next)-old*credits)/next,max,' GPA');}
 case 'gpa-credits':{const max=n('scale',1,10),old=n('current_gpa',0,max),credits=n('current_credits',0.000001,1e5),goal=n('target_gpa',0,max),future=n('future_gpa',0,max),step=n('credit_increment',0.000001,100);if(goal<=old)return {label:'ADDITIONAL CREDITS NEEDED',raw:0,value:'0',description:'Your current GPA already meets this target.'};if(future<=goal)return {label:'ADDITIONAL CREDITS NEEDED',raw:null,value:'Not reachable',description:'To raise a lower current GPA to this target in finite credits, your future average must exceed the target.'};const exact=credits*(goal-old)/(future-goal),needed=Math.ceil(exact/step-1e-10)*step;return result('ADDITIONAL CREDITS NEEDED',needed,'',`Rounded upward to your ${step}-credit increment. Estimated combined GPA: ${((old*credits+future*needed)/(credits+needed)).toFixed(4)}. Future credits must all average ${future}.`);}
 case 'retake-gpa':{const max=n('scale',1,10),g=n('current_gpa',0,max),credits=n('current_credits',0.000001,1e5),course=n('course_credits',0.000001,credits),old=n('old_points',0,max),next=n('new_points',0,max),rest=g*credits-old*course;if(rest<-EPS||rest>max*(credits-course)+EPS)throw new Error('Your GPA, credits and old course grade are inconsistent.');let q=g*credits,total=credits;if(v.policy==='replace')q+=(next-old)*course;else if(v.policy==='both'){q+=next*course;total+=course;}else throw new Error('Choose a retake policy.');return result('ESTIMATED GPA AFTER RETAKE',q/total,'',`Change from current GPA: ${(q/total-g).toFixed(4)}. ${total} GPA-bearing credits counted using the selected policy.`);}
 case 'weighted-gpa':{let q=0,credits=0;for(const [i,[base,c,bonus]] of parseTriples(v.rows).entries()){if(base>4||c<=0||bonus>2)throw new Error(`Row ${i+1}: base points 0–4, credits above zero, bonus 0–2.`);q+=(base+bonus)*c;credits+=c;}return result('CUSTOM WEIGHTED GPA',q/credits,'',`${q.toFixed(2)} boosted quality points ÷ ${credits.toFixed(2)} credits. Bonuses are supplied by you; no universal AP or honors policy is assumed.`);}
 case 'study-time':{const topics=count('topics',1),minutes=n('minutes_per_topic',0.000001,10000),days=count('days',1),review=n('review_percent',0,200);const total=topics*minutes*(1+review/100);return result('STUDY MINUTES PER DAY',total/days,' min',`${(total/60).toFixed(2)} total study hours across ${days} days, including ${review}% additional review time. This is a time budget, not a learning guarantee.`);}
 case 'reading-time':{const pages=n('pages',0.000001,1e6),words=n('words_per_page',0.000001,10000),speed=n('words_per_minute',0.000001,10000);return result('ESTIMATED READING TIME',pages*words/speed,' min',`${(pages*words).toFixed(0)} estimated words; ${(pages*words/speed/60).toFixed(2)} hours. Add your own time for notes, pauses and difficult passages.`);}
 case 'reading-speed':{const words=count('word_count',1),minutes=count('minutes'),seconds=n('seconds',0,59.999999),time=minutes+seconds/60;if(time<=0)throw new Error('Reading time must be greater than zero.');return result('READING SPEED',words/time,' WPM','Based on the words completed and elapsed reading time. Speed alone does not measure comprehension.');}
 case 'exam-time':{const duration=n('exam_minutes',0.000001,1440),reserve=n('review_minutes',0,duration),total=n('total_marks',0.000001,1e6),question=n('question_marks',0.000001,total);if(reserve>=duration)throw new Error('Leave some exam time after the review reserve.');const pace=(duration-reserve)/total;return result('TIME FOR THIS QUESTION',pace*question,' min',`${pace.toFixed(2)} minutes per mark across ${duration-reserve} working minutes. ${reserve} minutes reserved for checking. Adjust for different question demands.`);}
 default:throw new Error('Unknown calculator.');
 }
}
